from pathlib import Path
import subprocess,os,json,hashlib,statistics,math
binaries={'base':Path('/tmp/logex-commit-replay-base-bench'),'candidate':Path('/private/tmp/logex-bundled-pr130-final-query-tests')}
assert hashlib.sha256(binaries['base'].read_bytes()).hexdigest()=='548753bcbcdac60957d18c2603c40dd66fd7eea853a19c396e1e457542f74cdb'
assert hashlib.sha256(binaries['candidate'].read_bytes()).hexdigest()=='3aadf1f6deb619d7a5282907eea6ab2f048a02b24b658c3ec61f229bbf11a2fa'
metadata={'kind':'environment','base':'09a63f555db19a03850ce5eba6f149957febaf3b','candidate':'13588219204375c54821d3cfab83e6a4cf6b3cf2','fixture_version':1,'runner_source':Path(__file__).read_text(),'hardware':subprocess.check_output(['sysctl','-n','hw.model','hw.memsize','hw.ncpu'],text=True),'os':subprocess.check_output(['sw_vers'],text=True),'rustc':subprocess.check_output(['rustc','-Vv'],text=True),'filesystem':subprocess.check_output(['df','-h','/private/tmp'],text=True),'conditions':'Five alternating process pairs per dense/sparse profile, nine fresh datasets per process, 200000 rows, 50000 segment target, 8192-row batches, four query workers. Identical fixture v1 digests and exact native/SQL/reopen oracles required. Warm query paths, no cache eviction, no concurrent local build or test workload. Candidate follows independent index publication without obsolete segment refresh. Candidate includes final checkpoint in generic WAL live timing; baseline publishes each write. These row-only write APIs do not measure the new combined live sync path or network throughput. Reopen follows compaction; it is warm-cache startup. RSS includes all fixture/query/expected buffers.'}
root='/Users/tdenisenko/code/logex'
output='/tmp/logex-pr130-final-query-performance.jsonl'
with open(output,'w') as out:
 out.write(json.dumps(metadata)+'\n')
 for label in ['base','candidate']:
  binary=str(binaries[label])
  out.write(json.dumps({'kind':'binary','revision':label,'sha256':hashlib.sha256(open(binary,'rb').read()).hexdigest()})+'\n')
 for pair in range(5):
  for profile in ['dense','sparse']:
   for label in (['base','candidate'] if pair%2==0 else ['candidate','base']):
    log=f'/tmp/logex-pr130-final-query-{profile}-{pair}-{label}.log'
    env=os.environ|{'LOGEX_BENCH_PROFILE':profile,'LOGEX_BENCH_ROWS':'200000','LOGEX_BENCH_REPEATS':'9','LOGEX_BENCH_SEGMENT_ROWS':'50000','LOGEX_BENCH_BATCH_ROWS':'8192','LOGEX_BENCH_WORKERS':'4'}
    with open(log,'w') as capture:
     r=subprocess.run(['/usr/bin/time','-l',str(binaries[label]),'benchmark_storage_indexes_and_queries','--ignored','--nocapture','--test-threads=1'],env=env,stdout=capture,stderr=subprocess.STDOUT)
    if r.returncode: raise RuntimeError(f'{log}: {r.returncode}')
    for line in open(log):
     if '{' in line:
      try: record=json.loads(line[line.index('{'):])
      except json.JSONDecodeError: continue
      out.write(json.dumps(record|{'revision':label,'pair':pair,'profile':profile})+'\n')
     elif 'maximum resident set size' in line:
      out.write(json.dumps({'kind':'rss','revision':label,'pair':pair,'profile':profile,'bytes':int(line.split()[0])})+'\n')
    out.flush();print(pair,profile,label,'passed',flush=True)

records=[json.loads(line)for line in Path(output).read_text().splitlines()]
with open(output,'a')as out:
 for profile in ['dense','sparse']:
  configs=[r for r in records if r.get('kind')=='config'and r['profile']==profile]
  assert len(configs)==10 and len({r['fixture_digest']for r in configs})==1
  for metric in sorted({r['metric']for r in records if r.get('kind')=='sample'}):
   values={label:[r['elapsed_ms']for r in records if r.get('kind')=='sample'and r['metric']==metric and r['profile']==profile and r['revision']==label]for label in binaries}
   assert all(len(v)==45 for v in values.values())
   medians={label:statistics.median(v)for label,v in values.items()}
   record={'kind':'paired_summary','profile':profile,'metric':metric,'median_ms':medians,'p95_ms':{label:sorted(v)[math.ceil(.95*len(v))-1]for label,v in values.items()},'change_percent':100*(medians['candidate']/medians['base']-1),'samples_per_revision':45}
   out.write(json.dumps(record)+'\n');print(record,flush=True)
